enum UserscriptManagerRequest {
    Refresh {
        root: PathBuf,
    },
    Install {
        root: PathBuf,
        source: PathBuf,
    },
    Remove {
        root: PathBuf,
        name: String,
    },
    SetEnabled {
        root: PathBuf,
        name: String,
        enabled: bool,
    },
}

#[derive(Debug)]
enum UserscriptManagerResult {
    Inventory(Result<Vec<userscript::InstalledScript>, String>),
    Installed(Result<Vec<userscript::InstalledScript>, String>),
    Removed(Result<Vec<userscript::InstalledScript>, String>),
    SetEnabled {
        enabled: bool,
        result: Result<Vec<userscript::InstalledScript>, String>,
    },
}

struct UserscriptManagerWorker {
    inner: SingleFlightWorker<UserscriptManagerRequest, UserscriptManagerResult>,
}

enum ProfileMutation {
    Create {
        roots: StorageRoots,
        name: String,
        label: String,
    },
    Rename {
        roots: StorageRoots,
        name: String,
        label: String,
    },
    Delete {
        roots: StorageRoots,
        name: String,
        active_profile_id: Option<Uuid>,
    },
}

enum ProfileMutationResult {
    Created,
    Renamed,
    Deleted(ProfileDeletionOutcome),
}

impl UserscriptManagerWorker {
    fn spawn() -> Result<Self, String> {
        let inner = SingleFlightWorker::spawn(
            "ferric-browser-userscript-manager",
            |request: UserscriptManagerRequest| match request {
                UserscriptManagerRequest::Refresh { root } => {
                    UserscriptManagerResult::Inventory(userscript::installed_scripts(&root))
                }
                UserscriptManagerRequest::Install { root, source } => {
                    let result = userscript::install_manifest(&root, &source)
                        .and_then(|_installed_name| userscript::installed_scripts(&root));
                    UserscriptManagerResult::Installed(result)
                }
                UserscriptManagerRequest::Remove { root, name } => {
                    let result = userscript::remove(&root, &name)
                        .and_then(|()| userscript::installed_scripts(&root));
                    UserscriptManagerResult::Removed(result)
                }
                UserscriptManagerRequest::SetEnabled {
                    root,
                    name,
                    enabled,
                } => {
                    let result = userscript::set_enabled(&root, &name, enabled)
                        .and_then(|()| userscript::installed_scripts(&root));
                    UserscriptManagerResult::SetEnabled { enabled, result }
                }
            },
        )
        .map_err(|error| error.to_string())?;
        Ok(Self { inner })
    }

    fn request(&mut self, request: UserscriptManagerRequest) -> Result<(), String> {
        match self.inner.submit(request) {
            Ok(()) => Ok(()),
            Err(SubmitError::Busy) => Err("userscript manager is already busy".into()),
            Err(SubmitError::QueueFull) => Err("userscript manager queue is full".into()),
            Err(SubmitError::Stopped) => Err("userscript manager stopped".into()),
        }
    }

    fn poll(&mut self) -> Option<UserscriptManagerResult> {
        match self.inner.poll() {
            WorkerPoll::Pending => None,
            WorkerPoll::Ready(result) => Some(result),
            WorkerPoll::Stopped => Some(UserscriptManagerResult::Inventory(Err(
                "userscript manager stopped".into(),
            ))),
        }
    }
}

fn profile_delete_preview_text(roots: &StorageRoots, name: &str) -> Result<String, String> {
    let registry = ProfileRegistry::open(roots)
        .map_err(|error| format!("profile registry unavailable: {error}"))?;
    let profile = registry
        .profiles()
        .iter()
        .find(|profile| profile.name == name)
        .ok_or_else(|| "profile was not found".to_owned())?;
    Ok(format!(
        "Profile: {}\nUUID: {}\nRust data: {}\nSession data: {}\nCache: {}\nQtWebEngine storage is not deleted by this operation.",
        profile.name,
        profile.id,
        roots
            .data
            .join("profiles")
            .join(profile.id.to_string())
            .display(),
        roots
            .state
            .join("sessions")
            .join(profile.id.to_string())
            .display(),
        roots
            .cache
            .join("profiles")
            .join(profile.id.to_string())
            .display(),
    ))
}

impl ProfileDeleteWorker {
    fn spawn() -> Result<Self, String> {
        let inner = SingleFlightWorker::spawn(
            "ferric-browser-profile-mutator",
            |request: ProfileMutation| {
                (|| match request {
                    ProfileMutation::Create { roots, name, label } => {
                        let mut registry = ProfileRegistry::open(&roots)
                            .map_err(|error| format!("profile registry unavailable: {error}"))?;
                        registry
                            .create(&name, &label, ProfilePrivacy::Normal)
                            .map_err(|error| format!("profile creation failed: {error}"))?;
                        Ok(ProfileMutationResult::Created)
                    }
                    ProfileMutation::Rename { roots, name, label } => {
                        let mut registry = ProfileRegistry::open(&roots)
                            .map_err(|error| format!("profile registry unavailable: {error}"))?;
                        registry
                            .rename_label(&name, &label)
                            .map_err(|error| format!("profile rename failed: {error}"))?;
                        Ok(ProfileMutationResult::Renamed)
                    }
                    ProfileMutation::Delete {
                        roots,
                        name,
                        active_profile_id,
                    } => {
                        let registry = ProfileRegistry::open(&roots)
                            .map_err(|error| format!("profile registry unavailable: {error}"))?;
                        let profile = registry
                            .profiles()
                            .iter()
                            .find(|profile| profile.name == name)
                            .cloned()
                            .ok_or_else(|| "profile was not found".to_owned())?;
                        if active_profile_id == Some(profile.id)
                            || ProfileLock::is_held(&roots, profile.id)
                        {
                            return Err("profile is loaded and cannot be deleted".into());
                        }
                        let outcome = delete_profile_transaction(&roots, &profile.name)
                            .map_err(|error| error.to_string())?;
                        Ok(ProfileMutationResult::Deleted(outcome))
                    }
                })()
            },
        )
        .map_err(|error| error.to_string())?;
        Ok(Self { inner })
    }

    fn request_create(
        &mut self,
        roots: StorageRoots,
        name: String,
        label: String,
    ) -> Result<(), String> {
        self.request(ProfileMutation::Create { roots, name, label })
    }

    fn request_rename(
        &mut self,
        roots: StorageRoots,
        name: String,
        label: String,
    ) -> Result<(), String> {
        self.request(ProfileMutation::Rename { roots, name, label })
    }

    fn request_delete(
        &mut self,
        roots: StorageRoots,
        name: String,
        active_profile_id: Option<Uuid>,
    ) -> Result<(), String> {
        self.request(ProfileMutation::Delete {
            roots,
            name,
            active_profile_id,
        })
    }

    fn request(&mut self, request: ProfileMutation) -> Result<(), String> {
        match self.inner.submit(request) {
            Ok(()) => Ok(()),
            Err(SubmitError::Busy) => Err("profile mutation is already pending".into()),
            Err(SubmitError::QueueFull) => Err("profile mutation queue is full".into()),
            Err(SubmitError::Stopped) => Err("profile mutation worker stopped".into()),
        }
    }

    fn poll(&mut self) -> Option<Result<ProfileMutationResult, String>> {
        match self.inner.poll() {
            WorkerPoll::Pending => None,
            WorkerPoll::Ready(result) => Some(result),
            WorkerPoll::Stopped => Some(Err("profile deletion worker stopped".into())),
        }
    }
}

impl ProfileSetupWorker {
    fn spawn() -> Result<Self, String> {
        let inner = SingleFlightWorker::spawn(
            "ferric-browser-profile-bootstrap",
            |(transient, name, label, base, config_path, contexts_json): ProfileSetupRequest| {
                open_profile_store(transient, &name, &label, &base).map(|storage| {
                    let profile_overrides = if transient || config_path.is_empty() {
                        None
                    } else {
                        Some(load_profile_overrides(Path::new(&config_path), &name))
                    };
                    let runtime_overrides = if transient {
                        None
                    } else {
                        storage.5.as_ref().map(|roots| {
                            load_runtime_overrides(roots.state.join("runtime-overrides.toml"))
                                .map_err(|error| error.to_string())
                        })
                    };
                    let config_sources = if config_path.is_empty() {
                        None
                    } else {
                        Some(
                            load(Path::new(&config_path))
                                .map(|loaded| {
                                    let mut sources = loaded.sources;
                                    let profiles_path =
                                        profile_config_path(Path::new(&config_path));
                                    if profiles_path.exists() {
                                        sources.push(profiles_path);
                                    }
                                    sources
                                })
                                .map_err(|error| error.to_string()),
                        )
                    };
                    let contexts = storage.5.as_ref().map(|roots| {
                        let mut contexts =
                            ContextRegistry::open(roots).map_err(|error| error.to_string())?;
                        let mut context_error = None;
                        match serde_json::from_str::<ContextsConfig>(&contexts_json) {
                            Ok(definitions) => {
                                for definition in definitions.contexts {
                                    let profile_exists = storage
                                        .6
                                        .iter()
                                        .any(|profile| profile == &definition.profile);
                                    if !profile_exists {
                                        context_error = Some(format!(
                                            "context {} references missing profile {}",
                                            definition.name, definition.profile
                                        ));
                                        continue;
                                    }
                                    if let Err(error) = contexts.ensure_definition(
                                        &definition.name,
                                        &definition.label,
                                        &definition.profile,
                                        definition.sessions,
                                        definition.workspace,
                                        definition.accent,
                                        &definition.default_target,
                                    ) {
                                        context_error = Some(error.to_string());
                                    }
                                }
                            }
                            Err(error) => context_error = Some(error.to_string()),
                        }
                        Ok((contexts, context_error))
                    });
                    (
                        storage,
                        profile_overrides,
                        runtime_overrides,
                        config_sources,
                        contexts,
                    )
                })
            },
        )
        .map_err(|error| error.to_string())?;
        Ok(Self { inner })
    }

    fn request(
        &mut self,
        transient: bool,
        name: String,
        label: String,
        base: String,
        config_path: String,
        contexts_json: String,
    ) -> Result<(), String> {
        match self
            .inner
            .submit((transient, name, label, base, config_path, contexts_json))
        {
            Ok(()) => Ok(()),
            Err(SubmitError::Busy) => Err("profile bootstrap is already pending".into()),
            Err(SubmitError::QueueFull) => Err("profile bootstrap queue is full".into()),
            Err(SubmitError::Stopped) => Err("profile bootstrap worker stopped".into()),
        }
    }

    fn poll(&mut self) -> Option<Result<ProfileBootstrapSetup, String>> {
        match self.inner.poll() {
            WorkerPoll::Pending => None,
            WorkerPoll::Ready(result) => Some(result),
            WorkerPoll::Stopped => Some(Err("profile bootstrap worker stopped".into())),
        }
    }
}

