fn external_hint_target(value: &str) -> Option<&str> {
    let name = value.strip_prefix("external:")?;
    (is_bounded_untrusted_text(name)
        && name.chars().all(|character| {
            character.is_ascii_lowercase() || character.is_ascii_digit() || character == '-'
        }))
    .then_some(name)
}

