    fn profile_delete_preview(self: Pin<&mut Self>, _name: &QString) -> QString {
        self.as_ref().rust().profile_preview_text.clone()
    }

    fn request_profile_delete_preview(mut self: Pin<&mut Self>, name: &QString) -> bool {
        let Some(roots) = self.as_ref().rust().storage_roots.clone() else {
            self.as_mut().set_profile_preview_pending(false);
            self.as_mut().set_profile_preview_text(QString::default());
            return false;
        };
        self.as_mut()
            .set_profile_preview_text(QString::from("Loading validated profile deletion preview…"));
        let result = {
            let mut rust = self.as_mut().rust_mut();
            rust.as_mut()
                .get_mut()
                .profile_preview_worker
                .as_mut()
                .ok_or_else(|| "profile preview reader is unavailable".to_owned())
                .and_then(|worker| worker.request(roots, name.to_string()))
        };
        match result {
            Ok(()) => {
                self.as_mut().set_profile_preview_pending(true);
                true
            }
            Err(error) => {
                self.as_mut().set_profile_preview_pending(false);
                self.as_mut().set_profile_preview_text(QString::default());
                self.as_mut()
                    .set_status_text(QString::from(format!("Profile preview failed: {error}")));
                false
            }
        }
    }

    fn delete_profile(mut self: Pin<&mut Self>, name: &QString, confirmed: bool) -> bool {
        if !confirmed {
            self.set_status_text(QString::from(
                "Profile deletion requires preview and confirmation",
            ));
            return false;
        }
        let Some(roots) = self.as_ref().rust().storage_roots.clone() else {
            self.set_status_text(QString::from(
                "Private profiles cannot delete durable profiles",
            ));
            return false;
        };
        let active_profile_id = self.as_ref().rust().profile_id;
        let name = name.to_string();
        let result = self
            .as_mut()
            .rust_mut()
            .as_mut()
            .get_mut()
            .profile_delete_worker
            .as_mut()
            .ok_or_else(|| "profile deletion worker is unavailable".to_owned())
            .and_then(|worker| worker.request_delete(roots, name, active_profile_id));
        match result {
            Ok(()) => {
                self.set_status_text(QString::from("Profile deletion queued"));
                true
            }
            Err(error) => {
                self.set_status_text(QString::from(format!("Profile deletion failed: {error}")));
                false
            }
        }
    }

    fn default_download_directory(self: Pin<&mut Self>) -> QString {
        QString::from(
            configured_download_directory_path(&self.as_ref().rust().config)
                .to_string_lossy()
                .as_ref(),
        )
    }

    fn offer_download(
        mut self: Pin<&mut Self>,
        id: &QString,
        source_url: &QString,
        suggested_name: &QString,
    ) -> QString {
        let safe_name = sanitize_download_filename(&suggested_name.to_string());
        let source = ValidatedUrl::parse(source_url.to_string())
            .ok()
            .filter(|url| is_safe_history_url(url.as_str()))
            .map_or_else(|| "[redacted]".into(), |url| url.to_string());
        if self.as_ref().rust().store.is_some() {
            let result = self.as_mut().create_download_via_worker(
                id.to_string(),
                source,
                String::new(),
                DownloadState::Offered,
                unix_timestamp(),
            );
            if let Err(error) = result {
                self.set_status_text(QString::from(format!(
                    "Download index unavailable: {error}"
                )));
            }
        }
        QString::from(safe_name)
    }

    fn accept_download(
        mut self: Pin<&mut Self>,
        id: &QString,
        directory: &QString,
        suggested_name: &QString,
    ) -> QString {
        let directory = PathBuf::from(directory.to_string());
        if let Err(error) = fs::create_dir_all(&directory) {
            self.set_status_text(QString::from(format!(
                "Download directory unavailable: {error}"
            )));
            return QString::default();
        }
        let path = match choose_download_path(
            &directory,
            &suggested_name.to_string(),
            CollisionPolicy::AutoRename,
        ) {
            Ok(path) => path,
            Err(error) => {
                self.set_status_text(QString::from(format!(
                    "Download destination rejected: {error}"
                )));
                return QString::default();
            }
        };
        let staged = match stage_download_path(
            self.as_ref().rust().storage_roots.as_ref(),
            self.as_ref().rust().session_id,
            &path,
        ) {
            Ok(staged) => staged,
            Err(error) => {
                self.set_status_text(QString::from(format!(
                    "Download staging unavailable: {error}"
                )));
                return QString::default();
            }
        };
        if self.as_ref().rust().store.is_some() {
            if let Err(error) = self.as_mut().set_download_destination_via_worker(
                id.to_string(),
                path.to_string_lossy().into_owned(),
            ) {
                cleanup_staged_download(&staged);
                self.set_status_text(QString::from(format!(
                    "Download index update failed: {error}"
                )));
                return QString::default();
            }
            if !self.as_mut().queue_download_update(DownloadUpdate {
                id: id.to_string(),
                state: DownloadState::InProgress,
                bytes_received: 0,
                completed_at: None,
            }) {
                cleanup_staged_download(&staged);
                return QString::default();
            }
        }
        self.as_mut()
            .rust_mut()
            .as_mut()
            .get_mut()
            .staged_downloads
            .insert(id.to_string(), staged);
        self.as_ref().rust().storage_library_dirty.set(true);
        path.file_name()
            .and_then(|name| name.to_str())
            .map_or_else(QString::default, QString::from)
    }

    fn accept_download_path(
        mut self: Pin<&mut Self>,
        id: &QString,
        selected_path: &QString,
    ) -> QString {
        let result = (|| {
            let path = PathBuf::from(selected_path.to_string());
            if !path.is_absolute() || selected_path.to_string().chars().any(char::is_control) {
                return Err("selected download path is not a safe absolute path".to_owned());
            }
            let name = path
                .file_name()
                .and_then(|name| name.to_str())
                .ok_or_else(|| "selected download path has no valid filename".to_owned())?;
            let directory = path
                .parent()
                .ok_or_else(|| "selected download path has no containing directory".to_owned())?;
            let chosen = choose_download_path(directory, name, CollisionPolicy::Ask)
                .map_err(|error| error.to_string())?;
            if chosen != path {
                return Err(
                    "selected download path is not a safe non-colliding destination".into(),
                );
            }
            let staged = stage_download_path(
                self.as_ref().rust().storage_roots.as_ref(),
                self.as_ref().rust().session_id,
                &path,
            )?;
            if self.as_ref().rust().store.is_some() {
                if let Err(error) = self.as_mut().set_download_destination_via_worker(
                    id.to_string(),
                    path.to_string_lossy().into_owned(),
                ) {
                    cleanup_staged_download(&staged);
                    return Err(error);
                }
                if !self.as_mut().queue_download_update(DownloadUpdate {
                    id: id.to_string(),
                    state: DownloadState::InProgress,
                    bytes_received: 0,
                    completed_at: None,
                }) {
                    cleanup_staged_download(&staged);
                    return Err("download lifecycle update could not be queued".into());
                }
            }
            self.as_mut()
                .rust_mut()
                .as_mut()
                .get_mut()
                .staged_downloads
                .insert(id.to_string(), staged);
            self.as_ref().rust().storage_library_dirty.set(true);
            Ok(name.to_owned())
        })();
        match result {
            Ok(name) => QString::from(name),
            Err(error) => {
                self.set_status_text(QString::from(format!(
                    "Download destination rejected: {error}"
                )));
                QString::default()
            }
        }
    }

    fn download_staging_directory(self: Pin<&mut Self>, id: &QString) -> QString {
        self.as_ref()
            .rust()
            .staged_downloads
            .get(&id.to_string())
            .map_or_else(QString::default, |staged| {
                QString::from(staged.staging_directory.to_string_lossy().as_ref())
            })
    }

    fn finalize_download(mut self: Pin<&mut Self>, id: &QString) -> bool {
        let id_string = id.to_string();
        let Some(staged) = self
            .as_ref()
            .rust()
            .staged_downloads
            .get(&id_string)
            .cloned()
        else {
            self.set_status_text(QString::from("Download staging record is unavailable"));
            return false;
        };
        match finalize_staged_download(&staged) {
            Ok(()) => {
                self.as_mut()
                    .rust_mut()
                    .as_mut()
                    .get_mut()
                    .staged_downloads
                    .remove(&id_string);
                true
            }
            Err(error) => {
                cleanup_staged_download(&staged);
                self.as_mut()
                    .rust_mut()
                    .as_mut()
                    .get_mut()
                    .staged_downloads
                    .remove(&id_string);
                self.set_status_text(QString::from(format!(
                    "Download finalization failed: {error}"
                )));
                false
            }
        }
    }

    fn discard_download_staging(mut self: Pin<&mut Self>, id: &QString) {
        if let Some(staged) = self
            .as_mut()
            .rust_mut()
            .as_mut()
            .get_mut()
            .staged_downloads
            .remove(&id.to_string())
        {
            cleanup_staged_download(&staged);
        }
    }

    fn update_download(
        mut self: Pin<&mut Self>,
        id: &QString,
        state: &QString,
        bytes_received: i64,
        finished: bool,
    ) -> bool {
        let state = match state.to_string().as_str() {
            "offered" => DownloadState::Offered,
            "selecting-destination" => DownloadState::SelectingDestination,
            "in-progress" => DownloadState::InProgress,
            "paused" => DownloadState::Paused,
            "completed" => DownloadState::Completed,
            "interrupted" => DownloadState::Interrupted,
            "cancelled" => DownloadState::Cancelled,
            _ => {
                self.set_status_text(QString::from("Unknown download state"));
                return false;
            }
        };
        let completed_at = (finished && state == DownloadState::Completed).then(unix_timestamp);
        let update = DownloadUpdate {
            id: id.to_string(),
            state,
            bytes_received,
            completed_at,
        };
        if self.as_ref().rust().store.is_none() {
            return true;
        }
        self.as_mut().queue_download_update(update)
    }

    fn list_downloads(mut self: Pin<&mut Self>) -> QString {
        if self.as_ref().rust().storage_library.is_none()
            || self.as_ref().rust().storage_library_dirty.get()
        {
            self.as_mut().request_storage_library();
            if self.as_ref().rust().storage_library.is_none() {
                return QString::default();
            }
        }
        let binding = self.as_ref();
        let downloads = &binding
            .rust()
            .storage_library
            .as_ref()
            .expect("checked")
            .downloads;
        QString::from(
            downloads
                .iter()
                .map(|download| {
                    format!(
                        "{}\t{}\t{}\t{}",
                        download.id,
                        download.state.as_str(),
                        download.bytes_received,
                        download.destination.replace(['\t', '\n', '\r'], " ")
                    )
                })
                .collect::<Vec<_>>()
                .join("\n"),
        )
    }

    fn download_desktop_action(mut self: Pin<&mut Self>, id: &QString, reveal: bool) -> QString {
        if self.as_ref().rust().storage_library.is_none()
            || self.as_ref().rust().storage_library_dirty.get()
        {
            self.as_mut().request_storage_library();
        }
        let result = (|| {
            let binding = self.as_ref();
            let rust = binding.rust();
            if rust.storage_library_dirty.get() {
                return Err("download metadata is refreshing; retry the action".to_owned());
            }
            let library = rust
                .storage_library
                .as_ref()
                .ok_or_else(|| "download metadata is still loading; retry the action".to_owned())?;
            let record = library
                .downloads
                .iter()
                .find(|record| record.id == id.to_string())
                .cloned()
                .ok_or_else(|| "download ID was not found".to_owned())?;
            if record.state != DownloadState::Completed {
                return Err("only completed downloads can be opened or revealed".to_owned());
            }
            let destination = PathBuf::from(record.destination);
            let metadata = fs::symlink_metadata(&destination)
                .map_err(|error| format!("download file is unavailable: {error}"))?;
            if metadata.file_type().is_symlink() || !metadata.is_file() {
                return Err("completed download is not a regular file".to_owned());
            }
            let target = if reveal {
                destination
                    .parent()
                    .ok_or_else(|| "download has no containing directory".to_owned())?
                    .to_owned()
            } else {
                destination
            };
            if reveal
                && !fs::symlink_metadata(&target)
                    .map_err(|error| format!("download directory is unavailable: {error}"))?
                    .is_dir()
            {
                return Err("download containing path is not a directory".to_owned());
            }
            Ok(serde_json::json!({
                "id": id.to_string(),
                "uri": path_to_file_url(&target)?,
                "reveal": reveal
            }))
        })();
        match result {
            Ok(value) => QString::from(value.to_string()),
            Err(error) => {
                self.set_status_text(QString::from(error));
                QString::default()
            }
        }
    }

    fn execute_download_control_command(
        mut self: Pin<&mut Self>,
        command: &ParsedCommand,
    ) -> Result<Value, String> {
        self.as_ref()
            .rust()
            .registry
            .validate(command, self.as_ref().rust().core_mode)
            .map_err(|error| error.to_string())?;
        if command.arguments.len() != 1 {
            return Err(format!("{} requires exactly one download ID", command.name));
        }
        let action = command
            .name
            .strip_prefix("download-")
            .ok_or_else(|| "invalid download control command".to_owned())?;
        self.as_mut()
            .queue_download_action(&command.arguments[0], action)?;
        Ok(serde_json::json!({
            "status": "accepted",
            "download_id": command.arguments[0],
            "action": command.name
        }))
    }

    fn execute_permission_command(
        mut self: Pin<&mut Self>,
        command: &ParsedCommand,
    ) -> Result<Value, String> {
        self.as_ref()
            .rust()
            .registry
            .validate(command, self.as_ref().rust().core_mode)
            .map_err(|error| error.to_string())?;
        match command.name.as_str() {
            "permissions" => {
                if command.arguments.len() > 1 {
                    return Err("permissions accepts an optional exact origin".into());
                }
                let origin = command
                    .arguments
                    .first()
                    .map_or_else(QString::default, QString::from);
                let payload = self.as_mut().list_permissions(&origin).to_string();
                if payload.is_empty() {
                    return Err(self.as_ref().rust().status_text.to_string());
                }
                Ok(serde_json::from_str(&payload).map_err(|error| error.to_string())?)
            }
            "permission-reset" => {
                if command.arguments.len() != 2 {
                    return Err("permission-reset requires ORIGIN and PERMISSION".into());
                }
                if !self.as_mut().reset_permission(
                    &QString::from(command.arguments[0].as_str()),
                    &QString::from(command.arguments[1].as_str()),
                ) {
                    return Err(self.as_ref().rust().status_text.to_string());
                }
                Ok(serde_json::json!({"status": "reset"}))
            }
            _ => Err("unsupported permission command".into()),
        }
    }

    fn queue_download_action(
        mut self: Pin<&mut Self>,
        id: &str,
        action: &str,
    ) -> Result<(), String> {
        if self.as_ref().rust().store.is_none() {
            return Err("download metadata is unavailable in a private session".to_owned());
        }
        if self.as_ref().rust().storage_library_dirty.get() {
            self.as_mut().request_storage_library();
            return Err("download metadata is refreshing; retry the action".to_owned());
        }
        let library = self.as_ref().rust().storage_library.clone();
        let Some(library) = library else {
            self.as_mut().request_storage_library();
            return Err("download metadata is still loading; retry the action".to_owned());
        };
        let record = library
            .downloads
            .iter()
            .find(|record| record.id == id)
            .cloned()
            .ok_or_else(|| "download ID was not found".to_owned())?;
        let pending = match action {
            "cancel"
                if matches!(
                    record.state,
                    DownloadState::Offered
                        | DownloadState::SelectingDestination
                        | DownloadState::InProgress
                        | DownloadState::Paused
                ) =>
            {
                format!("download-cancel\t{id}")
            }
            "pause" if record.state == DownloadState::InProgress => {
                format!("download-pause\t{id}")
            }
            "resume" if record.state == DownloadState::Paused => {
                format!("download-resume\t{id}")
            }
            "retry"
                if matches!(
                    record.state,
                    DownloadState::Interrupted | DownloadState::Cancelled
                ) =>
            {
                let url = ValidatedUrl::parse(&record.source_url)
                    .map_err(|error| format!("download source is invalid: {error}"))?;
                let scheme = url.as_str().split_once(':').map(|(scheme, _)| scheme);
                if !matches!(scheme, Some("http" | "https")) {
                    return Err("download retry supports only HTTP(S) sources".into());
                }
                format!("download-retry\t{url}")
            }
            "cancel" => return Err("only active downloads can be cancelled".into()),
            "pause" => return Err("only in-progress downloads can be paused".into()),
            "resume" => return Err("only paused downloads can be resumed".into()),
            "retry" => return Err("only interrupted or cancelled downloads can be retried".into()),
            _ => return Err("unknown download action".into()),
        };
        self.as_mut()
            .rust_mut()
            .as_mut()
            .get_mut()
            .pending_engine_action = Some(pending);
        self.set_status_text(QString::from(match action {
            "cancel" => "Download cancellation requested",
            "pause" => "Download pause requested",
            "resume" => "Download resume requested",
            _ => "Download retry requested",
        }));
        Ok(())
    }

    fn request_download_action(mut self: Pin<&mut Self>, id: &QString, action: &QString) -> bool {
        match self
            .as_mut()
            .queue_download_action(&id.to_string(), &action.to_string())
        {
            Ok(()) => true,
            Err(error) => {
                self.set_status_text(QString::from(error));
                false
            }
        }
    }

    fn request_shutdown(mut self: Pin<&mut Self>) -> bool {
        match self.as_mut().reduce_event(Event::RequestShutdown) {
            Ok(_) => {
                self.set_status_text(QString::from("Shutdown requested"));
                true
            }
            Err(error) => {
                self.set_status_text(QString::from(format!("Shutdown rejected: {error}")));
                false
            }
        }
    }

    fn begin_shutdown_gate(mut self: Pin<&mut Self>) -> bool {
        let mut rust = self.as_mut().rust_mut();
        let this = rust.as_mut().get_mut();
        if this.ipc_shutdown_gate {
            return true;
        }
        this.ipc_shutdown_gate = true;
        self.set_status_text(QString::from("Shutdown gate active"));
        true
    }

    fn end_shutdown_gate(mut self: Pin<&mut Self>) {
        let mut rust = self.as_mut().rust_mut();
        rust.as_mut().get_mut().ipc_shutdown_gate = false;
    }

    fn force_quit(self: Pin<&mut Self>) {
        mark_forced_shutdown();
        self.set_status_text(QString::from(
            "Forced quit requested; crash marker preserved",
        ));
    }

    fn restart_software_rendering(
        self: Pin<&mut Self>,
        lock_path: &QString,
        storage_base: &QString,
        temporary_profile: bool,
        safe_mode: bool,
        userscripts_off: bool,
        instance_selector: &QString,
    ) -> bool {
        let _ = self;
        let lock_path = lock_path.to_string();
        if lock_path.is_empty() {
            return false;
        }
        let Ok(executable) = std::env::current_exe() else {
            return false;
        };
        let mut arguments = vec!["--software-rendering".to_owned()];
        if safe_mode {
            arguments.push("--safe-mode".to_owned());
        } else if userscripts_off {
            arguments.push("--userscripts-off".to_owned());
        } else if temporary_profile {
            arguments.push("--temp-basedir".to_owned());
        } else if !storage_base.is_empty() {
            arguments.extend(["--basedir".to_owned(), storage_base.to_string()]);
        }
        if !instance_selector.is_empty() {
            arguments.extend(["--instance".to_owned(), instance_selector.to_string()]);
        }
        let spawned = thread::Builder::new()
            .name("ferric-browser-software-restart".into())
            .spawn(move || {
                let lock_path = PathBuf::from(lock_path);
                let deadline = Instant::now() + Duration::from_secs(5);
                while lock_path.exists() && Instant::now() < deadline {
                    thread::sleep(Duration::from_millis(25));
                }
                if lock_path.exists() {
                    return;
                }
                let _ = Command::new(executable).args(arguments).spawn();
            });
        spawned.is_ok()
    }

    fn permission_decision(
        mut self: Pin<&mut Self>,
        origin: &QString,
        permission: &QString,
    ) -> QString {
        let origin = origin.to_string();
        let permission = permission.to_string();
        // Screen/window capture is intentionally per-request.  Unlike the
        // other permission types, it must never inherit a configured allow or
        // a remembered decision: the portal source chooser is part of the
        // consent boundary for every capture request.
        if permission == "screen-capture" {
            return QString::from("ask");
        }
        let normalized_origin = ferric_browser_storage::normalize_permission_origin(&origin).ok();
        let normal_profile = self.as_ref().rust().store.is_some();
        let permission_scope_id = self
            .as_ref()
            .rust()
            .profile_id
            .unwrap_or(self.as_ref().rust().session_id);
        if normal_profile
            && let Some(normalized_origin) = normalized_origin.as_deref()
            && let Some(rule) = self
                .as_ref()
                .rust()
                .config
                .get("permission_rules")
                .and_then(Value::as_array)
                .and_then(|rules| {
                    rules.iter().find(|rule| {
                        rule.get("profile").and_then(Value::as_str)
                            == Some(self.as_ref().rust().profile_name.as_str())
                            && rule.get("permission").and_then(Value::as_str)
                                == Some(permission.as_str())
                            && rule
                                .get("origin")
                                .and_then(Value::as_str)
                                .and_then(|origin| {
                                    ferric_browser_storage::normalize_permission_origin(origin).ok()
                                })
                                .as_deref()
                                == Some(normalized_origin)
                    })
                })
            && let Some(decision) = rule.get("decision").and_then(Value::as_str)
            && matches!(decision, "allow" | "deny" | "ask")
        {
            return QString::from(decision);
        }
        if normal_profile
            && (self.as_ref().rust().storage_library.is_none()
                || self.as_ref().rust().storage_library_dirty.get())
        {
            self.as_mut().request_storage_library();
        }
        if normal_profile
            && let Some(normalized_origin) = normalized_origin.as_deref()
            && !self.as_ref().rust().storage_library_dirty.get()
        {
            let durable = self
                .as_ref()
                .rust()
                .storage_library
                .as_ref()
                .into_iter()
                .flat_map(|library| library.permissions.iter())
                .find(|rule| {
                    rule.origin == normalized_origin
                        && rule.permission == permission
                        && rule
                            .expires_at
                            .is_none_or(|expires_at| expires_at > unix_timestamp())
                })
                .map(|rule| rule.decision.clone());
            if let Some(decision) = durable {
                return QString::from(decision.as_str());
            }
        }
        if let Some(normalized_origin) = normalized_origin.as_deref()
            && let Some(decision) =
                self.as_ref()
                    .rust()
                    .session_permissions
                    .get(&permission_session_key(
                        permission_scope_id,
                        normalized_origin,
                        &permission,
                    ))
        {
            return QString::from(decision.as_str());
        }
        let decision = match permission.as_str() {
            "camera" | "microphone" | "screen-capture" | "notifications" | "geolocation"
            | "clipboard" | "local-fonts" => {
                let key = permission.replace('-', "_");
                self.as_ref()
                    .rust()
                    .config
                    .get("permissions")
                    .and_then(|permissions| permissions.get(&key))
                    .and_then(Value::as_str)
                    .filter(|value| matches!(*value, "ask" | "allow" | "deny"))
                    .unwrap_or("ask")
                    .to_owned()
            }
            _ => "deny".to_owned(),
        };
        QString::from(decision.as_str())
    }

    fn remember_permission(
        mut self: Pin<&mut Self>,
        origin: &QString,
        permission: &QString,
        decision: &QString,
        lifetime: &QString,
    ) -> bool {
        let origin = origin.to_string();
        let permission = permission.to_string();
        let decision = decision.to_string();
        let lifetime = lifetime.to_string();
        if !matches!(decision.as_str(), "allow" | "deny") {
            self.set_status_text(QString::from("Permission decision must be allow or deny"));
            return false;
        }
        let result = if lifetime == "session" {
            let normalized_origin =
                match ferric_browser_storage::normalize_permission_origin(&origin) {
                    Ok(origin) => origin,
                    Err(error) => {
                        self.set_status_text(QString::from(format!(
                            "Permission session decision rejected: {error}"
                        )));
                        return false;
                    }
                };
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            let permission_scope_id = this.profile_id.unwrap_or(this.session_id);
            if permission == "camera-and-microphone" {
                this.session_permissions.insert(
                    permission_session_key(permission_scope_id, &normalized_origin, "camera"),
                    decision.clone(),
                );
                this.session_permissions.insert(
                    permission_session_key(permission_scope_id, &normalized_origin, "microphone"),
                    decision,
                );
            } else if matches!(
                permission.as_str(),
                "camera"
                    | "microphone"
                    | "notifications"
                    | "geolocation"
                    | "clipboard"
                    | "local-fonts"
            ) {
                this.session_permissions.insert(
                    permission_session_key(permission_scope_id, &normalized_origin, &permission),
                    decision,
                );
            } else {
                self.set_status_text(QString::from(
                    "Permission session decision is unsupported for this capability",
                ));
                return false;
            }
            Ok(())
        } else if lifetime == "site" {
            if self.as_ref().rust().store.is_none() {
                Err(ferric_browser_storage::StoreError::PrivateNoDurableState)
            } else {
                let normalized = ferric_browser_storage::normalize_permission_origin(&origin);
                match normalized {
                    Ok(normalized) => {
                        let permissions = if permission == "camera-and-microphone" {
                            vec!["camera", "microphone"]
                        } else {
                            vec![permission.as_str()]
                        };
                        if permissions.iter().any(|permission| {
                            !matches!(
                                *permission,
                                "camera"
                                    | "microphone"
                                    | "notifications"
                                    | "geolocation"
                                    | "clipboard"
                                    | "local-fonts"
                            )
                        }) {
                            Err(ferric_browser_storage::StoreError::InvalidInput(
                                "permission type is unsupported",
                            ))
                        } else {
                            let updated_at = unix_timestamp();
                            let rules = permissions
                                .into_iter()
                                .map(|permission| PermissionRule {
                                    origin: normalized.clone(),
                                    permission: permission.into(),
                                    decision: decision.clone(),
                                    expires_at: None,
                                    updated_at,
                                })
                                .collect::<Vec<_>>();
                            if self.as_mut().queue_permission_writes(rules) {
                                Ok(())
                            } else {
                                Err(ferric_browser_storage::StoreError::InvalidInput(
                                    "permission write queue is full",
                                ))
                            }
                        }
                    }
                    Err(error) => Err(error),
                }
            }
        } else {
            Err(ferric_browser_storage::StoreError::InvalidInput(
                "permission lifetime is unsupported",
            ))
        };
        match result {
            Ok(()) => {
                if lifetime != "session" {
                    self.as_ref().rust().storage_library_dirty.set(true);
                }
                self.set_status_text(QString::from(if lifetime == "session" {
                    "Permission session decision saved"
                } else {
                    "Permission rule queued"
                }));
                true
            }
            Err(error) => {
                self.set_status_text(QString::from(format!("Permission rule rejected: {error}")));
                false
            }
        }
    }

    fn list_permissions(mut self: Pin<&mut Self>, origin: &QString) -> QString {
        let origin = (!origin.to_string().is_empty()).then(|| origin.to_string());
        let private = self.as_ref().rust().store.is_none();
        if !private
            && (self.as_ref().rust().storage_library.is_none()
                || self.as_ref().rust().storage_library_dirty.get())
        {
            self.as_mut().request_storage_library();
            self.set_status_text(QString::from("Permission rules are still loading; retry"));
            return QString::from(
                serde_json::json!({
                    "status": "loading",
                    "private": false,
                    "ready": false,
                    "rules": []
                })
                .to_string(),
            );
        }
        let normalized_origin = match origin
            .as_deref()
            .map(ferric_browser_storage::normalize_permission_origin)
            .transpose()
        {
            Ok(origin) => origin,
            Err(error) => {
                self.set_status_text(QString::from(format!("Permissions unavailable: {error}")));
                return QString::default();
            }
        };
        let rules = self
            .as_ref()
            .rust()
            .storage_library
            .as_ref()
            .into_iter()
            .flat_map(|library| library.permissions.iter())
            .filter(|rule| {
                normalized_origin
                    .as_deref()
                    .is_none_or(|origin| rule.origin == origin)
            })
            .map(|rule| {
                serde_json::json!({
                    "origin": rule.origin,
                    "permission": rule.permission,
                    "decision": rule.decision,
                    "expires_at": rule.expires_at,
                    "updated_at": rule.updated_at
                })
            })
            .collect::<Vec<_>>();
        QString::from(
            serde_json::json!({
                "status": "listed",
                "private": private,
                "ready": true,
                "revision": self.as_ref().rust().storage_library_revision,
                "rules": rules
            })
            .to_string(),
        )
    }

    fn reset_permission(mut self: Pin<&mut Self>, origin: &QString, permission: &QString) -> bool {
        let origin = origin.to_string();
        let permission = permission.to_string();
        let session_removed = ferric_browser_storage::normalize_permission_origin(&origin)
            .is_ok_and(|origin| {
                let mut rust = self.as_mut().rust_mut();
                let this = rust.as_mut().get_mut();
                let permission_scope_id = this.profile_id.unwrap_or(this.session_id);
                if permission == "camera-and-microphone" {
                    this.session_permissions
                        .remove(&permission_session_key(
                            permission_scope_id,
                            &origin,
                            "camera",
                        ))
                        .is_some()
                        || this
                            .session_permissions
                            .remove(&permission_session_key(
                                permission_scope_id,
                                &origin,
                                "microphone",
                            ))
                            .is_some()
                } else {
                    this.session_permissions
                        .remove(&permission_session_key(
                            permission_scope_id,
                            &origin,
                            &permission,
                        ))
                        .is_some()
                }
            });
        let normalized = match ferric_browser_storage::normalize_permission_origin(&origin) {
            Ok(origin) => origin,
            Err(error) => {
                self.as_mut()
                    .set_status_text(QString::from(format!("Permission reset rejected: {error}")));
                return false;
            }
        };
        if permission == "screen-capture" {
            self.as_mut()
                .rust_mut()
                .as_mut()
                .get_mut()
                .pending_engine_action = Some(format!("permission-reset\t{origin}\t{permission}"));
            self.as_mut().set_status_text(QString::from(
                "Screen-capture consent reset; active captures will be stopped",
            ));
            return true;
        }
        let permissions = if permission == "camera-and-microphone" {
            vec!["camera".to_owned(), "microphone".to_owned()]
        } else if matches!(
            permission.as_str(),
            "camera" | "microphone" | "notifications" | "geolocation" | "clipboard" | "local-fonts"
        ) {
            vec![permission.clone()]
        } else {
            self.as_mut().set_status_text(QString::from(
                "Permission reset rejected: unsupported permission type",
            ));
            return false;
        };
        if self.as_ref().rust().store.is_none() {
            self.as_mut()
                .set_status_text(QString::from(if session_removed {
                    "Permission decision reset"
                } else {
                    "Permission rule was not found"
                }));
            if session_removed {
                self.as_mut()
                    .rust_mut()
                    .as_mut()
                    .get_mut()
                    .pending_engine_action =
                    Some(format!("permission-reset\t{origin}\t{permission}"));
            }
            return session_removed;
        }
        let request_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .map(|worker| worker.request_permission_reset(normalized, permissions))
        };
        match request_result {
            Some(Ok(())) => {
                let mut rust = self.as_mut().rust_mut();
                let this = rust.as_mut().get_mut();
                this.pending_permission_reset_session = Some(session_removed);
                this.storage_library_dirty.set(true);
                this.pending_engine_action =
                    Some(format!("permission-reset\t{origin}\t{permission}"));
                drop(rust);
                self.as_mut()
                    .set_status_text(QString::from("Permission reset queued"));
                true
            }
            Some(Err(error)) => {
                self.as_mut().set_status_text(QString::from(format!(
                    "Permission reset unavailable; retry the command: {error}"
                )));
                false
            }
            None => {
                self.as_mut().set_status_text(QString::from(
                    "Permission reset unavailable; retry the command",
                ));
                false
            }
        }
    }

    fn matching_page_scripts(
        self: Pin<&mut Self>,
        url: &QString,
        private_profile: bool,
    ) -> QString {
        let Some(roots) = self.as_ref().rust().userscript_roots.clone() else {
            return QString::from("[]");
        };
        match userscript::matching_page_scripts(&roots.config, &url.to_string(), private_profile) {
            Ok(scripts) => serde_json::to_string(&scripts).map_or_else(
                |error| {
                    self.set_status_text(QString::from(format!(
                        "Page userscript serialization failed: {error}"
                    )));
                    QString::from("[]")
                },
                QString::from,
            ),
            Err(error) => {
                self.set_status_text(QString::from(format!(
                    "Page userscripts unavailable: {error}"
                )));
                QString::from("[]")
            }
        }
    }

    fn refresh_userscript_inventory(mut self: Pin<&mut Self>) -> bool {
        if self.as_ref().active_profile_is_transient() {
            self.as_mut().set_userscript_inventory(QString::from("[]"));
            return true;
        }
        let Some(root) = self
            .as_ref()
            .rust()
            .userscript_roots
            .as_ref()
            .map(|roots| roots.config.clone())
        else {
            self.as_mut().set_userscript_inventory(QString::from("[]"));
            self.as_mut().set_status_text(QString::from(
                "Userscripts are unavailable without configured storage",
            ));
            return false;
        };
        let result = self
            .as_mut()
            .rust_mut()
            .as_mut()
            .get_mut()
            .userscript_manager_worker
            .as_mut()
            .ok_or_else(|| "userscript manager is unavailable".to_owned())
            .and_then(|worker| worker.request(UserscriptManagerRequest::Refresh { root }));
        if let Err(error) = result {
            self.as_mut()
                .set_userscript_install_state(QString::from(format!("error:{error}")));
            self.as_mut().set_status_text(QString::from(format!(
                "Userscript inventory unavailable: {error}"
            )));
            return false;
        }
        true
    }

    fn set_userscript_enabled(mut self: Pin<&mut Self>, name: &QString, enabled: bool) -> bool {
        let name = name.to_string();
        if self.as_ref().active_profile_is_transient() {
            self.as_mut().set_status_text(QString::from(
                "Userscript changes are unavailable in private or ephemeral profiles",
            ));
            return false;
        }
        if name.is_empty() || name.len() > 128 || name.chars().any(char::is_control) {
            self.as_mut()
                .set_status_text(QString::from("Userscript name is empty or invalid"));
            return false;
        }
        let Some(root) = self
            .as_ref()
            .rust()
            .userscript_roots
            .as_ref()
            .map(|roots| roots.config.clone())
        else {
            self.as_mut().set_status_text(QString::from(
                "Userscripts are unavailable without configured storage",
            ));
            return false;
        };
        let result = self
            .as_mut()
            .rust_mut()
            .as_mut()
            .get_mut()
            .userscript_manager_worker
            .as_mut()
            .ok_or_else(|| "userscript manager is unavailable".to_owned())
            .and_then(|worker| {
                worker.request(UserscriptManagerRequest::SetEnabled {
                    root,
                    name,
                    enabled,
                })
            });
        if let Err(error) = result {
            self.as_mut().set_status_text(QString::from(format!(
                "Userscript change rejected: {error}"
            )));
            return false;
        }
        self.as_mut()
            .set_userscript_install_state(QString::from("idle"));
        self.as_mut()
            .set_status_text(QString::from("Updating userscript enabled state…"));
        true
    }

    fn remove_userscript(mut self: Pin<&mut Self>, name: &QString) -> bool {
        if self.as_ref().active_profile_is_transient() {
            self.as_mut().set_status_text(QString::from(
                "Userscript removal is unavailable in private or ephemeral profiles",
            ));
            return false;
        }
        let name = name.to_string();
        if name.is_empty() || name.len() > 128 || name.chars().any(char::is_control) {
            self.as_mut()
                .set_status_text(QString::from("Userscript name is empty or invalid"));
            return false;
        }
        let Some(root) = self
            .as_ref()
            .rust()
            .userscript_roots
            .as_ref()
            .map(|roots| roots.config.clone())
        else {
            self.as_mut().set_status_text(QString::from(
                "Userscripts are unavailable without configured storage",
            ));
            return false;
        };
        let result = self
            .as_mut()
            .rust_mut()
            .as_mut()
            .get_mut()
            .userscript_manager_worker
            .as_mut()
            .ok_or_else(|| "userscript manager is unavailable".to_owned())
            .and_then(|worker| worker.request(UserscriptManagerRequest::Remove { root, name }));
        if let Err(error) = result {
            self.as_mut()
                .set_userscript_install_state(QString::from(format!("error:{error}")));
            self.as_mut().set_status_text(QString::from(format!(
                "Userscript removal rejected: {error}"
            )));
            return false;
        }
        self.as_mut()
            .set_userscript_install_state(QString::from("removing"));
        self.as_mut()
            .set_status_text(QString::from("Removing userscript…"));
        true
    }

    fn prepare_print_pdf(self: Pin<&mut Self>, path: &QString) -> QString {
        match validate_print_pdf_path(&path.to_string()) {
            Ok(path) => QString::from(path.to_string_lossy().as_ref()),
            Err(error) => {
                self.set_status_text(QString::from(error));
                QString::default()
            }
        }
    }

    fn prepare_save_page(mut self: Pin<&mut Self>, path: &QString) -> QString {
        match validate_save_page_path(&path.to_string()) {
            Ok(path) => {
                let path_string = path.to_string_lossy().into_owned();
                self.as_mut()
                    .rust_mut()
                    .as_mut()
                    .get_mut()
                    .pending_save_page = Some(path.clone());
                QString::from(path_string)
            }
            Err(error) => {
                self.set_status_text(QString::from(error));
                QString::default()
            }
        }
    }

    fn take_save_page_path(mut self: Pin<&mut Self>) -> QString {
        self.as_mut()
            .rust_mut()
            .as_mut()
            .get_mut()
            .pending_save_page
            .take()
            .map_or_else(QString::default, |path| {
                QString::from(path.to_string_lossy().as_ref())
            })
    }

    fn finish_print_pdf(self: Pin<&mut Self>, path: &QString, succeeded: bool) -> bool {
        let path_string = path.to_string();
        let result = if succeeded {
            validate_pdf_output_path(&path_string).and_then(|path| {
                let metadata = fs::symlink_metadata(&path)
                    .map_err(|error| format!("generated PDF is unavailable: {error}"))?;
                if metadata.file_type().is_symlink() || !metadata.is_file() {
                    return Err("generated PDF is not a regular file".into());
                }
                Ok(())
            })
        } else {
            Err("PDF generation failed; no completed PDF was produced".to_owned())
        };
        match result {
            Ok(()) => {
                self.set_status_text(QString::from("PDF generated"));
                true
            }
            Err(error) => {
                self.set_status_text(QString::from(error));
                false
            }
        }
    }

    fn prepare_print_job(mut self: Pin<&mut Self>) -> QString {
        if self.as_ref().rust().pending_print.is_some() {
            self.set_status_text(QString::from("A print job is already pending"));
            return QString::default();
        }
        let (directory, private_temporary) =
            self.as_ref().rust().storage_roots.as_ref().map_or_else(
                || {
                    (
                        std::env::temp_dir().join(format!(
                            "ferric-browser-print-{}",
                            self.as_ref().rust().session_id
                        )),
                        true,
                    )
                },
                |roots| (roots.runtime.join("print"), false),
            );
        if let Err(error) = fs::create_dir_all(&directory) {
            self.set_status_text(QString::from(format!(
                "Print staging directory is unavailable: {error}"
            )));
            return QString::default();
        }
        #[cfg(unix)]
        if let Err(error) = fs::set_permissions(
            &directory,
            std::os::unix::fs::PermissionsExt::from_mode(0o700),
        ) {
            self.set_status_text(QString::from(format!(
                "Print staging directory permissions could not be secured: {error}"
            )));
            return QString::default();
        }
        let path = directory.join(format!("{}.pdf", Uuid::new_v4()));
        {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.pending_print = Some(path.clone());
            this.pending_print_private = private_temporary;
        }
        if private_temporary {
            self.set_status_text(QString::from(
                "Rendering a private temporary PDF for desktop printing",
            ));
        }
        QString::from(path.to_string_lossy().as_ref())
    }

    fn finish_print_job(mut self: Pin<&mut Self>, path: &QString, succeeded: bool) -> bool {
        let path = PathBuf::from(path.to_string());
        let (requested, private_temporary) = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            (this.pending_print.clone(), this.pending_print_private)
        };
        if requested.as_ref() != Some(&path) {
            self.set_status_text(QString::from("Print request became stale"));
            return false;
        }
        if !succeeded {
            self.as_mut().rust_mut().as_mut().get_mut().pending_print = None;
            cleanup_print_artifact(&path, private_temporary);
            self.set_status_text(QString::from("Print failed: PDF generation failed"));
            return false;
        }
        let path = match validate_pdf_output_path(path.to_string_lossy().as_ref()) {
            Ok(path) => path,
            Err(error) => {
                self.as_mut().rust_mut().as_mut().get_mut().pending_print = None;
                cleanup_print_artifact(&path, private_temporary);
                self.set_status_text(QString::from(format!("Print failed: {error}")));
                return false;
            }
        };
        let request = self
            .as_mut()
            .rust_mut()
            .as_mut()
            .get_mut()
            .print_worker
            .as_mut()
            .ok_or_else(|| "print worker is unavailable".to_owned())
            .and_then(|worker| worker.request(path.clone()));
        if let Err(error) = request {
            self.as_mut().rust_mut().as_mut().get_mut().pending_print = None;
            cleanup_print_artifact(&path, private_temporary);
            self.set_status_text(QString::from(format!("Print failed: {error}")));
            return false;
        }
        self.set_status_text(QString::from("Print job queued"));
        true
    }

    fn take_download_request(mut self: Pin<&mut Self>) -> QString {
        let request_target = self
            .as_ref()
            .rust()
            .pending_download
            .as_ref()
            .map(|request| request.target);
        let request_is_stale = request_target.is_some_and(|target| {
            !captured_target_is_current(self.as_ref().rust().state.as_ref(), target)
        });
        let mut rust = self.as_mut().rust_mut();
        let this = rust.as_mut().get_mut();
        let Some(request) = this.pending_download.as_mut() else {
            return QString::default();
        };
        if request_is_stale {
            this.pending_download = None;
            self.set_status_text(QString::from("Download request is stale"));
            return QString::default();
        }
        if request.issued {
            return QString::default();
        }
        request.issued = true;
        QString::from(serde_json::json!({"token": request.token, "url": request.url}).to_string())
    }

    fn complete_download_request(
        mut self: Pin<&mut Self>,
        token: &QString,
        succeeded: bool,
    ) -> bool {
        let token = token.to_string();
        let request = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            let Some(request) = this.pending_download.as_ref() else {
                self.set_status_text(QString::from("Download request expired"));
                return false;
            };
            if request.token != token {
                self.set_status_text(QString::from("Download request is stale"));
                return false;
            }
            this.pending_download.take()
        };
        let Some(request) = request else {
            return false;
        };
        if !captured_target_is_current(self.as_ref().rust().state.as_ref(), request.target) {
            self.set_status_text(QString::from("Download request target is stale"));
            return false;
        }
        if succeeded {
            self.set_status_text(QString::from("Download activation requested"));
            true
        } else {
            self.set_status_text(QString::from("Download activation failed"));
            false
        }
    }

    #[allow(clippy::too_many_lines)]
    fn switcher_query(mut self: Pin<&mut Self>, query: &QString, scope: &QString) -> QString {
        if self.as_ref().rust().storage_library.is_none()
            || self.as_ref().rust().storage_library_dirty.get()
        {
            self.as_mut().request_storage_library();
        }
        self.as_mut().request_session_names();
        let scope = scope.to_string();
        let max_results = switcher_max_results(&self.as_ref().rust().config);
        let params = serde_json::json!({
            "query": query.to_string(),
            "scope": if scope.is_empty() { "all" } else { &scope },
            "limit": max_results,
            "include_private": self.as_ref().active_profile_is_transient(),
            "private_scope": self
                .as_ref()
                .active_profile_is_transient()
                .then(|| {
                    self.as_ref().rust().state.as_ref().and_then(|state| {
                        state
                            .active_tab()
                            .and_then(|tab| state.profiles().get(&tab.profile))
                            .map(|profile| profile.label.clone())
                    })
                })
                .flatten()
        });
        if let Some(cache) = self.as_ref().rust().switcher_cache.as_ref()
            && cache.matches(self.as_ref().rust(), &params)
        {
            return QString::from(cache.result.clone());
        }
        match self.as_ref().get_ref().ipc_switcher_query(&params) {
            Ok(result) => {
                let serialized = serde_json::to_string(&result).unwrap_or_else(|_| "{}".into());
                let mut rust = self.as_mut().rust_mut();
                let this = rust.as_mut().get_mut();
                this.switcher_cache = Some(SwitcherQueryCache {
                    params,
                    state_revision: this.state.as_ref().map_or(0, ApplicationState::revision),
                    storage_library_revision: this.storage_library_revision,
                    session_names: this.session_names.clone(),
                    contexts_json: this.contexts_json.to_string(),
                    config_fingerprint: serde_json::to_string(&this.config).unwrap_or_default(),
                    profile_name: this.profile_name.clone(),
                    result: serialized.clone(),
                });
                drop(rust);
                QString::from(serialized)
            }
            Err(error) => {
                self.set_status_text(QString::from(format!("Switcher query rejected: {error}")));
                QString::default()
            }
        }
    }

    fn request_storage_library(mut self: Pin<&mut Self>) {
        self.as_mut().ensure_storage_worker();
        let result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            if this.storage_library.is_some() && !this.storage_library_dirty.get() {
                return;
            }
            let result = this
                .storage_worker
                .as_mut()
                .map(|worker| worker.request_library(1_000));
            result
        };
        if let Some(Err(error)) = result
            && !matches!(error, ferric_browser_storage::StorageWorkerError::Busy)
        {
            self.set_status_text(QString::from(format!(
                "Profile metadata query unavailable: {error}"
            )));
        }
    }

    /// Build the durable switcher catalog away from the Qt thread. The
    /// snapshot is immutable and profile-local, so the worker can safely
    /// prepare the query-facing rows without touching Qt or SQLite.
    fn request_switcher_library_index(mut self: Pin<&mut Self>) {
        let (snapshot, revision, profile_name, result_slot, cancel) = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            let transient = this.state.as_ref().and_then(|state| {
                state
                    .active_tab()
                    .and_then(|tab| state.profiles().get(&tab.profile))
                    .map(|profile| profile.privacy.is_transient())
            }) == Some(true);
            if transient || this.storage_library_dirty.get() {
                return;
            }
            if this.switcher_library_index_building {
                if this.switcher_library_index_revision != this.storage_library_revision
                    && let Some(cancel) = this.switcher_library_index_cancel.as_ref()
                {
                    cancel.store(true, Ordering::Relaxed);
                }
                return;
            }
            if this.switcher_library_index.as_ref().is_some_and(|index| {
                this.switcher_library_index_revision == this.storage_library_revision
                    && index.profile_name == this.profile_name
            }) {
                return;
            }
            let Some(snapshot) = this.storage_library.clone() else {
                return;
            };
            this.switcher_library_index_building = true;
            let cancel = Arc::new(AtomicBool::new(false));
            this.switcher_library_index_cancel = Some(Arc::clone(&cancel));
            (
                snapshot,
                this.storage_library_revision,
                this.profile_name.clone(),
                Arc::clone(&this.switcher_library_index_result),
                cancel,
            )
        };
        let spawned = thread::Builder::new()
            .name("ferric-browser-switcher-index".into())
            .spawn(move || {
                let index = build_switcher_library_index(&snapshot, profile_name, &cancel);
                if let Ok(mut pending) = result_slot.lock() {
                    *pending = Some(SwitcherLibraryIndexResult { revision, index });
                }
            });
        if spawned.is_err() {
            self.as_mut()
                .rust_mut()
                .as_mut()
                .get_mut()
                .switcher_library_index_building = false;
            self.as_mut()
                .rust_mut()
                .as_mut()
                .get_mut()
                .switcher_library_index_cancel = None;
        }
    }

    fn poll_switcher_library_index(mut self: Pin<&mut Self>) -> bool {
        let result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.switcher_library_index_result
                .lock()
                .ok()
                .and_then(|mut pending| pending.take())
        };
        let Some(result) = result else {
            return false;
        };
        let mut rust = self.as_mut().rust_mut();
        let this = rust.as_mut().get_mut();
        this.switcher_library_index_building = false;
        this.switcher_library_index_cancel = None;
        let Some(index) = result.index else {
            return true;
        };
        let transient = this.state.as_ref().and_then(|state| {
            state
                .active_tab()
                .and_then(|tab| state.profiles().get(&tab.profile))
                .map(|profile| profile.privacy.is_transient())
        }) == Some(true);
        if result.revision != this.storage_library_revision
            || index.profile_name != this.profile_name
            || transient
        {
            return false;
        }
        this.switcher_library_index_revision = result.revision;
        this.switcher_library_index = Some(index);
        this.switcher_cache = None;
        true
    }

    fn ensure_storage_worker(mut self: Pin<&mut Self>) -> bool {
        if self.as_ref().rust().storage_worker.is_some() {
            return true;
        }
        let path = self
            .as_ref()
            .rust()
            .store
            .as_ref()
            .map(|store| store.path().to_owned());
        let Some(path) = path else {
            return false;
        };
        match ProfileStoreWorker::spawn(path) {
            Ok(worker) => {
                self.as_mut().rust_mut().as_mut().get_mut().storage_worker = Some(worker);
                self.set_status_text(QString::from("Profile metadata worker restarted"));
                true
            }
            Err(error) => {
                self.set_status_text(QString::from(format!(
                    "Profile metadata worker restart unavailable: {error}"
                )));
                false
            }
        }
    }

    fn request_session_names(mut self: Pin<&mut Self>) {
        let request = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            if !this.session_names_dirty.get() {
                return;
            }
            // Private and ephemeral sessions have no durable session catalog.
            // Keep this explicit so a future in-memory session implementation
            // cannot accidentally route transient metadata to disk.
            let transient_profile = this.state.as_ref().and_then(|state| {
                let tab = state.active_tab()?;
                state
                    .profiles()
                    .get(&tab.profile)
                    .map(|profile| profile.privacy.is_transient())
            }) == Some(true);
            if transient_profile {
                this.session_names.clear();
                this.session_names_dirty.set(false);
                return;
            }
            let Some(root) = this.session_state_root.clone() else {
                this.session_names_dirty.set(false);
                return;
            };
            let Some(profile_id) = this.profile_id else {
                this.session_names_dirty.set(false);
                return;
            };
            this.storage_worker
                .as_mut()
                .map(|worker| worker.request_session_list(root, profile_id))
        };
        if let Some(Err(error)) = request
            && !matches!(
                error,
                ferric_browser_storage::StorageWorkerError::Busy
                    | ferric_browser_storage::StorageWorkerError::QueueFull
            )
        {
            self.set_status_text(QString::from(format!(
                "Session catalog unavailable: {error}"
            )));
        }
    }

    fn poll_storage_library(mut self: Pin<&mut Self>) -> bool {
        self.as_mut().ensure_storage_worker();
        let mut consumed = self.as_mut().poll_switcher_library_index();
        let library_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_library)
        };
        let history_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_history_batch)
        };
        let session_checkpoint_clear_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_session_checkpoint_clear)
        };
        if let Some(result) = session_checkpoint_clear_result {
            consumed = true;
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.session_checkpoint_clear_pending = false;
            drop(rust);
            if let Err(error) = result {
                self.as_mut().set_status_text(QString::from(format!(
                    "Stale session checkpoint cleanup failed; recovery data was retained: {error}"
                )));
            }
        }
        let session_delete_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_session_delete)
        };
        if let Some(result) = session_delete_result {
            consumed = true;
            match result {
                Ok(()) => {
                    self.as_ref().rust().session_names_dirty.set(true);
                    self.as_mut().request_session_names();
                    self.as_mut()
                        .set_status_text(QString::from("Session deleted"));
                }
                Err(error) => {
                    self.as_mut().set_status_text(QString::from(format!(
                        "Session deletion failed: {error}"
                    )));
                }
            }
        }
        let session_save_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_session_save)
        };
        if let Some(result) = session_save_result {
            consumed = true;
            let checkpoint_save = {
                let mut rust = self.as_mut().rust_mut();
                let this = rust.as_mut().get_mut();
                this.session_save_pending = false;
                this.session_save_checkpoint
            };
            match result {
                Ok(()) => {
                    let mut rust = self.as_mut().rust_mut();
                    let this = rust.as_mut().get_mut();
                    this.session_names_dirty.set(true);
                    if checkpoint_save {
                        this.checkpoint.dirty = false;
                        this.checkpoint.dirty_since_ms = None;
                        this.checkpoint.restore_pending = None;
                        this.checkpoint.last_saved_ms = elapsed_ms(this.binding_clock);
                    }
                    drop(rust);
                    self.as_mut()
                        .set_status_text(QString::from(if checkpoint_save {
                            "Session checkpoint saved"
                        } else {
                            "Session saved"
                        }));
                }
                Err(error) => {
                    self.as_mut().set_status_text(QString::from(format!(
                        "Session snapshot failed; changes retained: {error}"
                    )));
                }
            }
        }
        let session_restore_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_session_restore)
        };
        if let Some(result) = session_restore_result {
            consumed = true;
            let recovery_pending = {
                let mut rust = self.as_mut().rust_mut();
                rust.as_mut().get_mut().session_restore_recovery_pending
            };
            let restore_load_append = {
                let mut rust = self.as_mut().rust_mut();
                rust.as_mut().get_mut().session_restore_load_append.take()
            };
            {
                let mut rust = self.as_mut().rust_mut();
                let this = rust.as_mut().get_mut();
                this.session_restore_preview_pending = false;
                this.session_restore_recovery_pending = false;
            }
            if recovery_pending {
                match result {
                    Ok(snapshot)
                        if !snapshot.entries.is_empty() || !snapshot.closed_tabs.is_empty() =>
                    {
                        self.as_mut()
                            .restore_closed_tabs_from_snapshot(snapshot.closed_tabs);
                        let restored = self
                            .as_mut()
                            .restore_session_from_entries(snapshot.entries, false);
                        if restored.is_empty() {
                            self.as_mut()
                                .set_status_text(QString::from("Recovery could not be applied"));
                        } else {
                            self.as_mut()
                                .set_session_restore_values(QString::from(format!(
                                    "replace\n{restored}"
                                )));
                        }
                    }
                    Ok(_) => self
                        .as_mut()
                        .set_status_text(QString::from("Recovery session is empty")),
                    Err(error) => self
                        .as_mut()
                        .set_status_text(QString::from(format!("Recovery rejected: {error}"))),
                }
            } else if let Some(append) = restore_load_append {
                match result {
                    Ok(snapshot) if !snapshot.entries.is_empty() => {
                        let restored = self
                            .as_mut()
                            .restore_session_from_entries(snapshot.entries, append);
                        if restored.is_empty() {
                            self.as_mut().set_session_preview(QString::from(
                                "ERROR\tSession restore could not be applied",
                            ));
                        } else {
                            self.as_mut()
                                .set_session_restore_values(QString::from(format!(
                                    "{}\n{restored}",
                                    if append { "append" } else { "replace" }
                                )));
                            self.as_mut()
                                .set_status_text(QString::from("Session loaded"));
                        }
                    }
                    Ok(_) => {
                        self.as_mut()
                            .set_session_preview(QString::from("ERROR\tSaved session is empty"));
                    }
                    Err(error) => {
                        self.as_mut().set_session_preview(QString::from(format!(
                            "ERROR\tSession restore rejected: {error}"
                        )));
                    }
                }
            } else {
                match result {
                    Ok(snapshot) if !snapshot.entries.is_empty() => {
                        let contents = snapshot
                            .entries
                            .iter()
                            .map(|entry| {
                                entry
                                    .url
                                    .as_deref()
                                    .unwrap_or("[placeholder: navigation will not be replayed]")
                            })
                            .collect::<Vec<_>>()
                            .join("\n");
                        self.as_mut().set_session_preview(QString::from(format!(
                            "{} tab(s)\n{contents}",
                            snapshot.entries.len()
                        )));
                        self.as_mut()
                            .set_status_text(QString::from("Session preview ready"));
                    }
                    Ok(_) => {
                        self.as_mut()
                            .set_status_text(QString::from("Saved session is empty"));
                    }
                    Err(error) => {
                        self.as_mut().set_status_text(QString::from(format!(
                            "Session preview rejected: {error}"
                        )));
                    }
                }
            }
        }
        let session_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_session_list)
        };
        if let Some(result) = session_result {
            consumed = true;
            match result {
                Ok(names) => {
                    let mut rust = self.as_mut().rust_mut();
                    let this = rust.as_mut().get_mut();
                    this.session_names = names;
                    this.session_names_dirty.set(false);
                }
                Err(error) => {
                    self.as_mut().set_status_text(QString::from(format!(
                        "Session catalog query failed: {error}"
                    )));
                }
            }
        }
        if let Some(result) = library_result {
            consumed = true;
            match result {
                Ok(snapshot) => {
                    let mut rust = self.as_mut().rust_mut();
                    let this = rust.as_mut().get_mut();
                    this.storage_library = Some(snapshot);
                    this.storage_library_revision = this.storage_library_revision.saturating_add(1);
                    this.storage_library_dirty.set(
                        this.inflight_history_writes.is_some()
                            || !this.pending_history_writes.is_empty()
                            || this.inflight_permission_writes.is_some()
                            || !this.pending_permission_writes.is_empty()
                            || this.inflight_mark_writes.is_some()
                            || !this.pending_mark_writes.is_empty()
                            || this.inflight_download_writes.is_some()
                            || !this.pending_download_writes.is_empty(),
                    );
                }
                Err(error) => {
                    let mut rust = self.as_mut().rust_mut();
                    let this = rust.as_mut().get_mut();
                    this.storage_worker = None;
                    this.storage_library = None;
                    this.storage_library_dirty.set(false);
                    drop(rust);
                    self.as_mut().set_status_text(QString::from(format!(
                        "Profile metadata query failed: {error}"
                    )));
                }
            }
        }
        self.as_mut().request_switcher_library_index();
        let journey_node_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_journey_node)
        };
        if let Some(result) = journey_node_result {
            consumed = true;
            let pending = self
                .as_mut()
                .rust_mut()
                .as_mut()
                .get_mut()
                .pending_journey_reopen
                .take();
            match (pending, result) {
                (Some((node_id, target_kind, current_tab, profile_id)), Ok(Some(node))) => {
                    if node.id != node_id || node.profile_id != profile_id {
                        self.as_mut().set_status_text(QString::from(
                            "Journey node is stale or belongs to another profile",
                        ));
                    } else {
                        let record = JourneyReopenRecord {
                            id: node.id,
                            url: node.url,
                        };
                        let reopen_result = self.as_mut().finish_journey_reopen(
                            record,
                            &target_kind,
                            current_tab,
                            Some(profile_id),
                        );
                        match reopen_result {
                            Ok(_) => self
                                .as_mut()
                                .set_status_text(QString::from("Journey reopened")),
                            Err(error) => self.as_mut().set_status_text(QString::from(error)),
                        }
                    }
                }
                (Some(_), Ok(None)) => self
                    .as_mut()
                    .set_status_text(QString::from("Journey node is stale or unavailable")),
                (Some(_), Err(error)) => self.as_mut().set_status_text(QString::from(format!(
                    "Journey node lookup failed: {error}"
                ))),
                (None, _) => self
                    .as_mut()
                    .set_status_text(QString::from("Journey reopen request expired")),
            }
        }
        let journey_query_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_journey_query)
        };
        if let Some(result) = journey_query_result {
            consumed = true;
            match result {
                Ok(snapshot) => {
                    self.as_mut().apply_journey_query_snapshot(snapshot);
                    self.as_mut()
                        .set_status_text(QString::from("Journey query ready"));
                }
                Err(error) => self
                    .as_mut()
                    .set_status_text(QString::from(format!("Journey query failed: {error}"))),
            }
        }
        let journey_export_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_journey_export)
        };
        if let Some(result) = journey_export_result {
            consumed = true;
            match result {
                Ok(snapshot) => {
                    let profile = self
                        .as_ref()
                        .rust()
                        .profile_id
                        .map_or_else(String::new, |id| id.to_string());
                    let payload = serde_json::to_string(&serde_json::json!({
                        "format": "ferric-browser-journey-v1",
                        "durability": "durable",
                        "profile": profile,
                        "nodes": snapshot.nodes.into_iter().map(|node| serde_json::json!({
                            "id": node.id,
                            "profile": node.profile_id,
                            "tab": node.tab_id,
                            "url": safe_ipc_url(&node.url),
                            "title": node.title,
                            "committed_at": node.committed_at,
                            "transition": node.transition,
                            "source": node.source,
                        })).collect::<Vec<_>>(),
                        "edges": snapshot.edges.into_iter().map(|edge| serde_json::json!({
                            "source": edge.source_id,
                            "target": edge.target_id,
                            "transition": edge.transition,
                            "created_at": edge.created_at,
                        })).collect::<Vec<_>>(),
                    }))
                    .unwrap_or_default();
                    let preview = Self::format_journey_export_preview(&payload);
                    let mut rust = self.as_mut().rust_mut();
                    let this = rust.as_mut().get_mut();
                    this.journey_export_payload = Some(payload);
                    drop(rust);
                    self.as_mut().set_journey_export_preview_text(preview);
                    self.as_mut()
                        .set_status_text(QString::from("Journey export preview ready"));
                }
                Err(error) => self.as_mut().set_status_text(QString::from(format!(
                    "Journey export unavailable: {error}"
                ))),
            }
        }
        if let Some(result) = history_result {
            consumed = true;
            self.as_mut().apply_history_batch_result(result);
        }
        let permission_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_permission_batch)
        };
        if let Some(result) = permission_result {
            consumed = true;
            self.as_mut().apply_permission_batch_result(result);
        }
        let permission_reset_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_permission_reset)
        };
        if let Some(result) = permission_reset_result {
            consumed = true;
            let session_removed = self
                .as_mut()
                .rust_mut()
                .as_mut()
                .get_mut()
                .pending_permission_reset_session
                .take()
                .unwrap_or(false);
            match result {
                Ok(true) => {
                    self.as_ref().rust().storage_library_dirty.set(true);
                    self.as_mut()
                        .set_status_text(QString::from(if session_removed {
                            "Permission decision reset"
                        } else {
                            "Permission rule reset"
                        }));
                }
                Ok(false) if session_removed => {
                    self.as_mut()
                        .set_status_text(QString::from("Permission decision reset"));
                }
                Ok(false) => self
                    .as_mut()
                    .set_status_text(QString::from("Permission rule was not found")),
                Err(error) => self.as_mut().set_status_text(QString::from(format!(
                    "Permission reset failed; retry is available: {error}"
                ))),
            }
        }
        let download_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_download_batch)
        };
        if let Some(result) = download_result {
            consumed = true;
            self.as_mut().apply_download_batch_result(result);
        }
        let mark_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_mark_write)
        };
        if let Some(result) = mark_result {
            consumed = true;
            let batch = self
                .as_mut()
                .rust_mut()
                .as_mut()
                .get_mut()
                .inflight_mark_writes
                .take();
            match result {
                Ok(committed) if batch.as_ref().is_some_and(|batch| committed == batch.len()) => {
                    self.as_ref().rust().storage_library_dirty.set(true);
                    self.as_mut()
                        .set_status_text(QString::from("Bookmark/quickmark write committed"));
                }
                Ok(committed) => {
                    if let Some(batch) = batch {
                        let mut rust = self.as_mut().rust_mut();
                        let this = rust.as_mut().get_mut();
                        for write in batch.into_iter().rev() {
                            this.pending_mark_writes.push_front(write);
                        }
                    }
                    self.as_mut().rust_mut().as_mut().get_mut().storage_worker = None;
                    self.as_mut().set_status_text(QString::from(format!(
                        "Bookmark/quickmark worker committed an unexpected count ({committed})"
                    )));
                }
                Err(error) => {
                    if let Some(batch) = batch {
                        let mut rust = self.as_mut().rust_mut();
                        let this = rust.as_mut().get_mut();
                        for write in batch.into_iter().rev() {
                            this.pending_mark_writes.push_front(write);
                        }
                    }
                    self.as_mut().rust_mut().as_mut().get_mut().storage_worker = None;
                    self.as_mut().set_status_text(QString::from(format!(
                        "Bookmark/quickmark worker write failed; retry retained: {error}"
                    )));
                }
            }
        }
        let history_clear_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_history_clear)
        };
        if let Some(result) = history_clear_result {
            consumed = true;
            let clear_filter = self
                .as_mut()
                .rust_mut()
                .as_mut()
                .get_mut()
                .pending_history_clear
                .take();
            match result {
                Ok(deleted) => {
                    if let Some((since, origin)) = clear_filter {
                        let cutoff = since.and_then(|value| u64::try_from(value).ok());
                        if self
                            .as_mut()
                            .reduce_event(Event::ClearJourney {
                                since: cutoff,
                                origin,
                            })
                            .is_ok()
                        {
                            let mut rust = self.as_mut().rust_mut();
                            let this = rust.as_mut().get_mut();
                            if let Some(state) = this.state.as_ref() {
                                let retained = this
                                    .journey_durable_ids
                                    .borrow()
                                    .iter()
                                    .filter(|(node, _)| state.journey().node(**node).is_some())
                                    .map(|(node, durable)| (*node, durable.clone()))
                                    .collect();
                                this.journey_durable_ids.replace(retained);
                            }
                        }
                    }
                    self.as_ref().rust().storage_library_dirty.set(true);
                    self.as_mut().set_status_text(QString::from(format!(
                        "History cleared ({deleted} entries deleted)"
                    )));
                }
                Err(error) => {
                    self.as_mut()
                        .set_status_text(QString::from(format!("History clear failed: {error}")));
                }
            }
        }
        let download_destination_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_download_destination)
        };
        if let Some(result) = download_destination_result {
            consumed = true;
            match result {
                Ok(()) => {
                    self.as_ref().rust().storage_library_dirty.set(true);
                }
                Err(error) => {
                    self.as_mut().set_status_text(QString::from(format!(
                        "Download destination update failed: {error}"
                    )));
                }
            }
        }
        let download_create_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_download_create)
        };
        if let Some(result) = download_create_result {
            consumed = true;
            match result {
                Ok(()) => {
                    self.as_ref().rust().storage_library_dirty.set(true);
                }
                Err(error) => {
                    self.as_mut().set_status_text(QString::from(format!(
                        "Download index creation failed: {error}"
                    )));
                }
            }
        }
        let journey_result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .and_then(ProfileStoreWorker::poll_journey_write)
        };
        if let Some(result) = journey_result {
            consumed = true;
            let mapping = self
                .as_mut()
                .rust_mut()
                .as_mut()
                .get_mut()
                .pending_journey_mapping
                .take();
            match result {
                Ok(true) => {
                    if let Some((core_id, durable_id)) = mapping {
                        self.as_ref()
                            .rust()
                            .journey_durable_ids
                            .borrow_mut()
                            .insert(core_id, durable_id);
                    }
                    self.as_ref().rust().storage_library_dirty.set(true);
                    let mut rust = self.as_mut().rust_mut();
                    let this = rust.as_mut().get_mut();
                    this.journey_export_payload = None;
                    this.journey_export_preview_text = QString::default();
                }
                Ok(false) => {
                    self.as_mut().set_status_text(QString::from(
                        "Journey worker did not find the requested current node",
                    ));
                }
                Err(error) => {
                    self.as_mut().set_status_text(QString::from(format!(
                        "Journey worker write failed: {error}"
                    )));
                }
            }
            self.as_mut().flush_journey_writes();
        }
        // A journey request may have been deferred while another storage
        // mutation occupied the worker. Retry it on every storage poll so the
        // bounded queue cannot wait for a journey response that never arrives.
        self.as_mut().flush_journey_writes();
        self.as_mut().flush_history_writes();
        self.as_mut().flush_permission_writes();
        self.as_mut().flush_mark_writes();
        self.as_mut().flush_download_writes();
        consumed
    }

    fn apply_mark_write(mut self: Pin<&mut Self>, write: MarkWrite) -> Result<(), String> {
        if self.as_ref().rust().storage_worker.is_none() {
            return Err("profile metadata worker is unavailable".to_owned());
        }
        if self.as_ref().rust().pending_mark_writes.len() >= MAX_PENDING_MARK_WRITES {
            return Err("bookmark/quickmark write queue is full; retry the mark command".into());
        }
        self.as_mut()
            .rust_mut()
            .as_mut()
            .get_mut()
            .pending_mark_writes
            .push_back(write);
        self.as_ref().rust().storage_library_dirty.set(true);
        self.as_mut().flush_mark_writes();
        self.set_status_text(QString::from("Bookmark/quickmark write queued"));
        Ok(())
    }

    fn queue_bookmark_transfer(mut self: Pin<&mut Self>, url: &QString, title: &QString) -> bool {
        if self.as_ref().active_profile_is_transient() {
            self.as_mut().set_status_text(QString::from(
                "Private and ephemeral profiles cannot receive durable bookmarks",
            ));
            return false;
        }
        let url = url.to_string();
        if !is_safe_history_url(&url) {
            self.as_mut()
                .set_status_text(QString::from("Bookmark transfer URL is not eligible"));
            return false;
        }
        let title = sanitize_untrusted_title(&title.to_string());
        if self
            .as_mut()
            .apply_mark_write(MarkWrite::AddBookmark {
                id: Uuid::new_v4().to_string(),
                url,
                title,
                timestamp: unix_timestamp(),
            })
            .is_err()
        {
            return false;
        }
        true
    }

    fn clear_history_via_worker(
        mut self: Pin<&mut Self>,
        since: Option<i64>,
        origin: Option<String>,
    ) -> Result<(), String> {
        let result = {
            let mut rust = self.as_mut().rust_mut();
            let this = rust.as_mut().get_mut();
            this.storage_worker
                .as_mut()
                .map(|worker| worker.request_history_clear(since, origin.clone()))
        };
        match result {
            Some(Ok(())) => {
                self.as_mut()
                    .rust_mut()
                    .as_mut()
                    .get_mut()
                    .pending_history_clear = Some((since, origin.clone()));
                self.as_ref().rust().storage_library_dirty.set(true);
                self.as_mut()
                    .set_status_text(QString::from("History clear queued"));
                Ok(())
            }
            Some(Err(
                ferric_browser_storage::StorageWorkerError::Busy
                | ferric_browser_storage::StorageWorkerError::QueueFull,
            )) => Err("profile metadata worker is busy; retry history clear".into()),
            Some(Err(error)) => Err(error.to_string()),
            None => Err("profile metadata worker is unavailable".to_owned()),
        }
    }

